begin;
select no_plan();
insert into public.profiles(id) values('00000000-0000-4000-8000-000000001701'),('00000000-0000-4000-8000-000000001702');
insert into private.clerk_issuers(issuer,authorized_parties,enabled) values('https://clerk.erasure.test',array['https://app.invalid'],true);
insert into public.account_identities(issuer,subject,account_id) values('https://clerk.erasure.test','user_eeeeeeeeeeeeeeeeeeeeeeeeeee','00000000-0000-4000-8000-000000001702');
select * from public.operational_access_set('00000000-0000-4000-8000-000000001701','owner','grant','test:mail-r2','Owner fixture','test:mail-r2',null);
create function pg_temp.mail(action text,params jsonb default '{}') returns jsonb language sql as $$
select public.mail_admin_execute('00000000-0000-4000-8000-000000001701',action,params,'sandbox') $$;
select public.mail_record_consent('00000000-0000-4000-8000-000000001702','old@example.invalid','es',true,'verified_settings',false);
select public.mail_record_consent('00000000-0000-4000-8000-000000001702','current@example.invalid','es',true,'verified_settings',false);
create temporary table sync as select pg_temp.mail('mail_sync_lease','{"email":"current@example.invalid","revision":1}') data;
select is((select data->'allowed' from sync),'true'::jsonb,'sync lease acquired before erasure');
select public.apply_clerk_user_event('mail-r2-erasure',repeat('a',64),'https://clerk.erasure.test','user_eeeeeeeeeeeeeeeeeeeeeeeeeee','user.deleted',now(),null);
select is((select count(*)::integer from private.mail_contacts),0,'#1622 event removes current and previous contacts');
select is((select count(*)::integer from private.mail_contact_erasures),2,'#1622 event durably queues both provider erasures');
select is((pg_temp.mail('mail_list')->'cleanup'->>'pending')::integer,2,'Owner can inspect pending erasures without addresses');
select is(pg_temp.mail('mail_sync_lease','{"email":"current@example.invalid","revision":1}')->'allowed','false'::jsonb,'erased snapshot cannot start a new provider sync');
select ok((select next_attempt_at>clock_timestamp() from private.mail_contact_erasures where email='current@example.invalid'),'in-flight sync drains before provider deletion');
select throws_ok($$select public.mail_record_consent(null,'current@example.invalid','en',true,'verified_waitlist',true)$$,'40001','mail_erasure_pending','new consent cannot race pending provider deletion');
select ok(not has_function_privilege('anon','public.mail_erasure_claim()','execute'),'anon cannot drain queue');
select ok(not has_function_privilege('authenticated','public.mail_erasure_finish(uuid,uuid,integer)','execute'),'client cannot forge provider ACK');
select ok(not has_table_privilege('service_role','private.mail_contact_erasures','select'),'queue PII inaccessible through generic table API');
create temporary table claimed as select public.mail_erasure_claim()->'job' job;
select is((select job->>'email' from claimed),'old@example.invalid','only unleased address is eligible');
select is(public.mail_erasure_finish((select (job->>'id')::uuid from claimed),(select (job->>'lease')::uuid from claimed),503),true,'failure persisted for retry');
select is((select state from private.mail_contact_erasures where email='old@example.invalid'),'pending','failed DELETE stays pending');
select ok((select next_attempt_at>now() from private.mail_contact_erasures where email='old@example.invalid'),'retry uses backoff');
select is(public.mail_erasure_claim()->'job','null'::jsonb,'neither backoff nor active sync can be bypassed');
update private.mail_contact_erasures set next_attempt_at=now()-interval '1 second' where email='old@example.invalid';
create temporary table retry as select public.mail_erasure_claim()->'job' job;
select isnt((select job->>'lease' from retry),(select job->>'lease' from claimed),'retry has a new fencing token');
select is(public.mail_erasure_finish((select (job->>'id')::uuid from claimed),(select (job->>'lease')::uuid from claimed),204),false,'stale ACK cannot finish a newer lease');
select is(public.mail_erasure_finish((select (job->>'id')::uuid from retry),(select (job->>'lease')::uuid from retry),204),true,'provider DELETE receipt completes job');
select is((select email from private.mail_contact_erasures where id=(select (job->>'id')::uuid from retry)),null,'provider ACK removes temporary email from queue');
select is((select outcome from private.mail_contact_erasures where id=(select (job->>'id')::uuid from retry)),'deleted','successful result retained without PII');
update private.mail_contact_erasures set next_attempt_at=now()-interval '1 second' where email='current@example.invalid';
create temporary table missing as select public.mail_erasure_claim()->'job' job;
select is(public.mail_erasure_finish((select (job->>'id')::uuid from missing),(select (job->>'lease')::uuid from missing),404),true,'Brevo already absent is an idempotent success');
select is((select count(*)::integer from private.mail_contact_erasures where state='completed'),2,'all provider erasures confirmed');
select is(public.mail_erasure_claim()->'job','null'::jsonb,'completed contacts never delete twice');
select ok(not exists(select 1 from private.mail_audit where detail::text like '%example.invalid%'),'erasure audit contains no email');
select * from finish();
rollback;
